import{_ as l,o as i,c as e,ae as t}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"明細の分割（帳単位）","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/09-bill-split-guide.md","filePath":"v1/ja/guide/09-bill-split-guide.md"}'),r={name:"v1/ja/guide/09-bill-split-guide.md"};function o(h,a,d,n,s,u){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="明細の分割-帳単位" tabindex="-1">明細の分割（帳単位） <a class="header-anchor" href="#明細の分割-帳単位" aria-label="Permalink to &quot;明細の分割（帳単位）&quot;">​</a></h1><h2 id="_1-この機能について" tabindex="-1">1. この機能について <a class="header-anchor" href="#_1-この機能について" aria-label="Permalink to &quot;1. この機能について&quot;">​</a></h2><p>1回の支払いに複数の用途が含まれる場合（例：「スーパー」で果物と日用品を一緒に買ったなど）、1つの明細を複数の子明細に分割して、カテゴリ別の集計をより正確にできます。</p><p>分割後：</p><ul><li>複数の「子明細」（それぞれにカテゴリ・金額・メモ）として表示されます。</li><li>元の明細は「分割用のコンテナ」として扱われ、一覧表示や集計から除外されます（重複計上を防ぐため）。</li></ul><h2 id="_2-こんなときに便利" tabindex="-1">2. こんなときに便利 <a class="header-anchor" href="#_2-こんなときに便利" aria-label="Permalink to &quot;2. こんなときに便利&quot;">​</a></h2><ul><li>1回の支払いに複数カテゴリが混在している（食費 + 日用品、交通 + 駐車場など）</li><li>カテゴリ別の分析や予算比較をより細かく行いたい</li><li>1枚のレシートを複数カテゴリ/タグに分けて記録したい</li></ul><h2 id="_3-使い方" tabindex="-1">3. 使い方 <a class="header-anchor" href="#_3-使い方" aria-label="Permalink to &quot;3. 使い方&quot;">​</a></h2><ol><li>明細一覧で分割したい明細を見つける</li><li>その明細を左にスワイプして「分割」を選ぶ</li><li>「明細分割」画面で： <ul><li>子項目の「カテゴリ」をタップしてカテゴリを選択</li><li>「金額」をタップして各子項目の金額を入力</li><li>メモは任意（補足用）</li><li>行を増やす場合は「追加」をタップ</li></ul></li><li>「残り（未配分）金額」が 0 になっていることを確認（子項目の合計が元の金額と一致）</li><li>右上の「完了/保存」をタップ</li></ol><h2 id="_4-ルールと注意点" tabindex="-1">4. ルールと注意点 <a class="header-anchor" href="#_4-ルールと注意点" aria-label="Permalink to &quot;4. ルールと注意点&quot;">​</a></h2><ul><li>子項目の合計金額は元の明細金額と一致している必要があります。一致しない場合は保存できません。</li><li>各子項目はカテゴリの選択が必須で、金額は 0 より大きい必要があります。</li><li>集計は子明細を基準に行われ、元の明細は集計に含まれません。</li><li>多段階の分割に対応しています。子明細も再度分割でき、最終的な集計は末端の子明細（リーフ）を基準に行われます。</li><li>分割と精算（報銷）は併用できません。精算対象（精算待ち/精算済み等）の支出明細は分割できず、分割済みの明細も精算フローを開始できません。まず精算が必要かを決め、そのうえで分割するか判断してください。</li></ul><h2 id="_5-よくある質問" tabindex="-1">5. よくある質問 <a class="header-anchor" href="#_5-よくある質問" aria-label="Permalink to &quot;5. よくある質問&quot;">​</a></h2><h3 id="q1-分割後、元の明細はどこに行きますか" tabindex="-1">Q1：分割後、元の明細はどこに行きますか？ <a class="header-anchor" href="#q1-分割後、元の明細はどこに行きますか" aria-label="Permalink to &quot;Q1：分割後、元の明細はどこに行きますか？&quot;">​</a></h3><p>重複計上を防ぐため、元の明細は「分割用コンテナ」として扱われ、通常は一覧に表示されません。集計は子明細を基準に行われます。</p><h3 id="q2-一部だけ分割できますか" tabindex="-1">Q2：一部だけ分割できますか？ <a class="header-anchor" href="#q2-一部だけ分割できますか" aria-label="Permalink to &quot;Q2：一部だけ分割できますか？&quot;">​</a></h3><p>可能です。1行を「その他/元のカテゴリ」として残し、金額を残額にすればOKです。重要なのは、子項目の合計が元の金額と一致することです。</p><h3 id="q3-分割後に編集できますか" tabindex="-1">Q3：分割後に編集できますか？ <a class="header-anchor" href="#q3-分割後に編集できますか" aria-label="Permalink to &quot;Q3：分割後に編集できますか？&quot;">​</a></h3><p>基本は子明細側（金額/カテゴリ/メモ）を編集してください。分割をやり直したい場合は、関連する子明細を削除してから再度分割するのが一般的です。</p>',18)])])}const p=l(r,[["render",o]]);export{c as __pageData,p as default};
